let modalLastFocus=null,toastTimer,pollTimer;const activeStatus=s=>['queued','running'].includes(s);const statusName=s=>({pending:'待执行',queued:'排队中',running:'运行中',succeeded:'已完成',failed:'运行失败',cancelled:'已取消',draft:'草案',published:'已发布'}[s]||s||'待运行');const statusTag=s=>`<span class="tag ${s==='failed'?'red':s==='running'?'blue':s==='cancelled'?'neutral':''}">${esc(statusName(s))}</span>`;const stamp=s=>s?new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
