async function api(path,{method='GET',body}={}){
 const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),path==='/data-sources/search'?45000:path==='/integrations/tianditu/check'?25000:path.startsWith('/public/')?18000:12000);
 try{const r=await fetch('/api'+path,{method,signal:controller.signal,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json()}catch{throw Error('本地 API 未响应，请检查平台服务。')}if(!r.ok)throw Error(d.error?.message||'请求未完成，请重试');return d}
 catch(e){if(e.name==='AbortError')throw Error('请求超时，请稍后重试。未生成替代数据。');throw e}finally{clearTimeout(timer)}
}
function button(label,action,ico='arrow',cls='',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${icon(ico)}${label}</button>`}
function heading(title,desc,actions='',label='SPATIAL INTELLIGENCE WORKSPACE'){return `<div class="heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function empty(title,desc,action=''){return `<div class="empty"><div class="empty-icon">${icon('layers')}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`}
function showDialog(title,content,actions=''){modalLastFocus=document.activeElement;$('#dialog').innerHTML=`<button class="dialog-close" data-action="close-dialog" aria-label="关闭弹窗">${icon('close')}</button><h2 id="dialog-title">${title}</h2>${content}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;$('#dialog').showModal();$('#dialog').querySelector('input,select,textarea,button')?.focus()}
function closeDialog(){$('#dialog').close();modalLastFocus?.focus()}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});$('#dialog').addEventListener('close',()=>modalLastFocus?.focus());
function go(v){if(!NAV.some(n=>n[0]===v))v='overview';if(!state.professionalMode&&!['overview','map'].includes(v))v='overview';state.view=v;location.hash=v;$('#sidebar').classList.remove('open');render();window.scrollTo(0,0)}
function renderNav(){const mapView=['overview','map'].includes(state.view),tab=state.clientTab||'applications';$('#nav').innerHTML=[['map','地图','map'],['applications','专题分析','layers'],['history','任务与成果','clock']].map(([id,name,ico])=>`<button class="nav-link ${mapView&&tab===id?'active':''}" data-action="client-tab" data-tab="${id}" title="${name}" ${mapView&&tab===id?'aria-current="page"':''}>${icon(ico)}<span>${name}</span></button>`).join('')+`<button class="nav-link ${state.view==='data'?'active':''}" data-action="open-sources" title="数据">${icon('data')}<span>数据</span></button><div class="nav-spacer"></div><button class="nav-link nav-professional" data-action="professional-tools" title="专业工具">${icon('grid')}<span>专业工具</span></button>`;$('#breadcrumb').textContent=mapView?({map:'地图',applications:'专题分析',history:'任务与成果',chat:'结果详情'}[tab]||'专题分析'):NAV.find(n=>n[0]===state.view)?.[1]||'地图'}

function pathSteps(){return `<div class="progress-path">${[['01','描述需求'],['02','编排分析'],['03','成果上图'],['04','组装应用'],['05','能力共享']].map(([i,n],j)=>`${j?'<span class="path-arrow"></span>':''}<span class="path-step ${j===0||state.plans.length&&j===1||state.runs.some(r=>r.status==='succeeded')&&j===2||state.apps.length&&j===3||state.apps.some(a=>a.status==='published')&&j===4?'active':''}"><b>${i}</b>${n}</span>`).join('')}</div>`}
function overviewLegacy(){const b=state.boot;let metrics=[['可计算数据集',state.datasets?.length||0,'份','来源独立标识 · 按需选择','data'],['可用算法工具',state.algorithms?.length||0,'项','空间统计 · 最近邻 · NDVI','flow'],['已归档分析',state.analyses?.length||0,'次','数据版本与参数可追溯','layers'],['工作空间应用',state.apps.length,'个',`${state.apps.filter(a=>a.status==='published').length} 个已在本机发布`,'app']];return `${heading('让时空数据，成为决策的力量','连接数据、智能与业务，构建从需求到应用的全新工作方式。',button('平台指南','guide','info','secondary-mobile-hide')+button('新建智能任务','new-plan','plus','primary'))}<div class="stats">${metrics.map(([l,v,u,d,i])=>`<article class="stat"><div class="stat-label">${l}</div><span class="stat-icon">${icon(i)}</span><div class="stat-value">${v}<small>${u}</small></div><div class="stat-note"><b>${d}</b><span>本地工作空间</span></div></article>`).join('')}</div>${pathSteps()}<div class="dashboard"><div class="dashboard-left">${mapPanel()}<div class="section-heading"><h2>从业务现场，连接空间智能<small>围绕仙桃农业的真实应用需求</small></h2><button class="text-button" data-action="all-scenes">全部场景 ${icon('arrow')}</button></div><div class="scene-grid">${['crop','farmland','eel'].map(id=>scenarioCard(state.boot.scenarios.find(s=>s.id===id))).join('')}</div></div><aside class="panel assistant"><div class="assistant-head"><span class="assistant-symbol">${icon('spark')}</span><div><b>时空智能助手</b><small>GeoAI Copilot</small></div><span class="tag">需求规划</span></div><div class="assistant-body"><h3>从一个问题，<br>到一张<span>有答案的图。</span></h3><p>描述业务目标，协助拆解多主题需求、<br>识别数据缺口，形成可审阅的分析流程。</p><div class="suggestions">${[['crop','分析仙桃秋冬播种植变化','leaf'],['eel','构建黄鳝产业链专题一张图','cube'],['full','导入仙桃完整业务需求','flow']].map(([id,n,i])=>`<button class="suggestion" data-action="quick-prompt" data-id="${id}">${icon(i)}${n}<span>↗</span></button>`).join('')}</div><div class="prompt-box"><label class="sr-only" for="assistant-prompt">业务需求</label><textarea id="assistant-prompt" placeholder="描述区域、问题与预期成果…">${esc(state.requirement)}</textarea><div class="prompt-bottom"><span>需求梳理 · 流程建议</span><button class="send" data-action="assistant-plan" aria-label="生成需求计划">${icon('up')}</button></div></div></div><div class="assistant-foot">本地规则辅助规划 · 专业引擎按授权接入</div></aside></div>${taskRecords()}`}
function scenarioCard(s){if(!s)return '';const ix={crop:'leaf',farmland:'layers',eel:'water'}[s.id]||'cube';return `<button class="scene-card" data-action="scenario" data-id="${esc(s.id)}"><div class="scene-top"><span class="scene-symbol">${icon(ix)}</span><span class="tag ${s.id==='eel'?'amber':''}">场景模板</span></div><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="scene-bottom"><span>${esc(s.category)} · 组件可复用</span><span>探索场景 ↗</span></div></button>`}
function taskRecords(){return `<section class="panel task-panel"><div class="panel-heading"><h2>${icon('clock')}最近任务 <small>执行记录可跨页面与刷新恢复</small></h2><button class="text-button" data-action="tasks">查看任务 ${icon('arrow')}</button></div>${state.runs.length?state.runs.slice(0,3).map(r=>`<button class="task-row" style="width:100%;text-align:left" data-action="open-run" data-id="${esc(r.id)}"><span class="task-icon">${icon(r.status==='succeeded'?'check':'flow')}</span><b class="record-name">${esc(r.name)}</b>${statusTag(r.status)}<small>${stamp(r.created_at)}</small><span>${icon('right')}</span></button>`).join(''):`<div class="empty-inline"><span>工作流尚未运行。从一项需求开始，形成第一份可追溯成果。</span><button class="text-button" data-action="new-plan">创建任务 ${icon('arrow')}</button></div>`}</section>`}
const kindNames={farm:'农业资源',industry:'产业设施',alert:'核查线索',machine:'农机服务',water:'治理设施'};const colors={farm:'#7db694',industry:'#8aace0',alert:'#d8b36f',machine:'#a4c7aa',water:'#73b9b6'};
function allFeatures(){if(state.sourceGeoJSON)return state.sourceGeoJSON.features||[];const r=state.runs.find(r=>r.id===state.resultId);return r?.result?.geojson?.features||state.map.features||[]}
function visibleFeatures({builder=false}={}){let fs=builder?(state.map.features||[]):allFeatures();if(builder){const k=new Set();for(const id of state.appDraft.modules){if(id==='baseline')Object.keys(kindNames).forEach(v=>k.add(v));if(['crop','farmland','land'].includes(id))k.add('farm');if(['disaster','fishing','mobile'].includes(id))k.add('alert');if(['eel','coldchain'].includes(id))k.add('industry');if(id==='machinery')k.add('machine');if(id==='water')k.add('water')}return fs.filter(f=>k.has(f.properties?.kind))}return state.layer==='all'?fs:fs.filter(f=>f.properties?.kind===state.layer)}
function featureColor(p,builder=false){if(!builder&&state.mapAnalysis?.algorithm_id==='ndvi'){if(p.ndvi_status!=='valid'||typeof p.ndvi!=='number')return '#7d8da4';return p.ndvi<0?'#e39c82':p.ndvi<.2?'#d4bd75':p.ndvi<.5?'#a1c88c':'#63bfa4'}return colors[p.kind]||'#63b9ed'}
function mapLegend(builder=false){return !builder&&state.mapAnalysis?.algorithm_id==='ndvi'?`<div class="map-legend ndvi-legend"><span>NDVI</span><span><i style="background:#e39c82"></i>＜0</span><span><i style="background:#d4bd75"></i>0–0.2</span><span><i style="background:#a1c88c"></i>0.2–0.5</span><span><i style="background:#63bfa4"></i>≥0.5</span><span><i style="background:#7d8da4"></i>无效值</span></div>`:`<div class="map-legend"><span><i style="background:#65bfae"></i>农业资源</span><span><i style="background:#7c9de4"></i>产业设施</span><span><i style="background:#e0bb78"></i>核查线索</span><span><i style="background:#63b9ed"></i>其他要素</span></div>`}
const coordinateLabel=(lon,lat)=>Math.abs(lon).toFixed(4)+'° '+(lon<0?'W':'E')+' / '+Math.abs(lat).toFixed(4)+'° '+(lat<0?'S':'N');
function mapSVG({builder=false}={}){const fs=builder?visibleFeatures({builder:true}):visibleFeatures();const all=builder?state.map.features:allFeatures();const points=[];function walk(a){if(Array.isArray(a)&&typeof a[0]==='number')points.push(a);else if(Array.isArray(a))a.forEach(walk)}all.forEach(f=>walk(f.geometry?.coordinates));const merc=c=>[Number(c[0])*Math.PI/180,Math.log(Math.tan(Math.PI/4+Math.max(-85.05,Math.min(85.05,Number(c[1])))*Math.PI/360))];const xy=points.map(merc);let minX=-1,maxX=1,minY=-.5,maxY=.5;if(xy.length){minX=Math.min(...xy.map(c=>c[0]));maxX=Math.max(...xy.map(c=>c[0]));minY=Math.min(...xy.map(c=>c[1]));maxY=Math.max(...xy.map(c=>c[1]))}const dx=Math.max(.0001,maxX-minX),dy=Math.max(.0001,maxY-minY),scale=Math.min(740/dx,310/dy),cx=(minX+maxX)/2,cy=(minY+maxY)/2;const project=c=>{const v=merc(c);return[450+(v[0]-cx)*scale,225-(v[1]-cy)*scale]};const shapes=fs.map((f,i)=>{const p=f.properties||{},id=String(f.id??p.id??('index-'+i)),c=featureColor(p,builder);const name=p.name||p.id||'空间要素 '+(i+1);const poly=cs=>cs.map(r=>r.map(project).map((v,i)=>`${i?'L':'M'}${v.join(' ')}`).join(' ')+' Z').join(' ');let shape='';switch(f.geometry?.type){case 'Point':{const[x,y]=project(f.geometry.coordinates);shape=`<circle cx="${x}" cy="${y}" r="13" fill="${c}" opacity=".09"/><circle cx="${x}" cy="${y}" r="5" fill="${c}" opacity=".9" stroke="#cff3ff" stroke-width="1"/><circle cx="${x}" cy="${y}" r="2" fill="#fff"/>`;if(fs.length<25||i%5===0)shape+=`<text x="${x+11}" y="${y-9}" font-size="9" fill="#b2cde7" font-family="sans-serif">${esc(name).slice(0,35)}</text>`;break}case 'LineString':shape=`<polyline points="${f.geometry.coordinates.map(project).map(v=>v.join(',')).join(' ')}" fill="none" stroke="${c}" stroke-width="2"/>`;break;case 'Polygon':shape=`<path d="${poly(f.geometry.coordinates)}" fill="${c}" fill-opacity=".24" fill-rule="evenodd" stroke="${c}" stroke-width="1.4"/>`;break;case 'MultiPolygon':shape=f.geometry.coordinates.map(cs=>`<path d="${poly(cs)}" fill="${c}" fill-opacity=".24" fill-rule="evenodd" stroke="${c}" stroke-width="1.4"/>`).join('');break}return `<g class="map-feature" pointer-events="${f.geometry?.type==='Point'?'bounding-box':'auto'}" role="button" tabindex="0" aria-label="${esc(name)}" data-feature="${esc(id)}">${shape}</g>`}).join('');let grid='';for(let x=0;x<920;x+=50)grid+=`<path d="M${x} 0V450"/>`;for(let y=0;y<470;y+=50)grid+=`<path d="M0 ${y}H900"/>`;const bbox=points.length?[Math.min(...points.map(c=>c[0])),Math.min(...points.map(c=>c[1])),Math.max(...points.map(c=>c[0])),Math.max(...points.map(c=>c[1]))]:[];return `<svg class="map-svg" viewBox="0 0 900 450" preserveAspectRatio="xMidYMid meet" aria-label="空间数据坐标画布"><defs><radialGradient id="space-light"><stop stop-color="#183252"/><stop offset="1" stop-color="#101c33"/></radialGradient></defs><rect width="900" height="450" fill="url(#space-light)" pointer-events="none"/><g fill="none" stroke="#44689b" stroke-width=".45" opacity=".24">${grid}</g><g fill="none" stroke="#557dae" stroke-width=".6" opacity=".3"><path d="M450 0V450M0 225H900"/><circle cx="450" cy="225" r="145" stroke-dasharray="3 8"/><circle cx="450" cy="225" r="240" stroke-dasharray="1 12"/></g><g class="data-map-transform" transform="translate(${450-450*state.zoom+(state.panX||0)} ${225-225*state.zoom+(state.panY||0)}) scale(${state.zoom})">${shapes}</g><g fill="#6684ab" font-family="monospace" font-size="8"><text x="16" y="432">${bbox.length?coordinateLabel(bbox[0],bbox[1]):'NO SPATIAL FEATURES'}</text><text x="650" y="432">${bbox.length?coordinateLabel(bbox[2],bbox[3]):''}</text></g></svg>`}
function currentSource(){return state.mapSourceMeta||{name:'尚未选择空间图层',source_type:'unknown',source:'请上传业务数据或运行实际分析'}}
function mapPanel(full=false,builder=false){const meta=currentSource();return `<section class="panel ${full?'map-full':''}">${builder?'':`<div class="panel-heading"><h2>${icon('map')}${state.view==='overview'?'空间数据引擎':esc(meta.name||'空间数据画布')} <small>数据与来源同步可见</small></h2><button class="text-button" data-action="${full?'layer-info':'go-map'}">${full?'图层说明':'进入一张图'} ${icon('right')}</button></div><div class="map-toolbar"><div class="segmented">${[['all','全部要素'],['farm','农业资源'],['industry','产业设施'],['alert','核查线索']].map(([id,n])=>`<button class="${state.layer===id?'selected':''}" data-action="map-layer" data-id="${id}">${n}</button>`).join('')}</div>${sourceBadge(meta.source_type)}</div>`}<div class="map-area">${mapSVG({builder})}<div class="map-status"><span class="map-chip"><i></i>${esc(meta.name||'空间要素')}</span><span class="map-chip">无地理底图 · 仅显示数据要素</span></div><div class="map-tools"><button data-action="zoom-in" aria-label="放大地图">${icon('plus')}</button><button data-action="zoom-out" aria-label="缩小地图">${icon('minus')}</button><button data-action="zoom-reset" aria-label="适应数据范围">${icon('locate')}</button><button data-action="layer-info" aria-label="图层说明">${icon('layers')}</button></div>${mapLegend(builder)}</div>${builder?'':`<div class="map-meta"><span>输入坐标 WGS84 · 显示投影 Web Mercator</span><span>${visibleFeatures().length} 个要素 · 拖动平移 / 按钮缩放</span></div>`}</section>`}
function mapView(){const completed=state.runs.filter(r=>r.status==='succeeded'&&r.result),result=state.mapAnalysis||state.runs.find(r=>r.id===state.resultId)?.result;return `${heading('让分析结果，回到空间现场','选择数据或分析成果，地图将自动适应实际坐标范围。',button('导出 GeoJSON','export-map','download','secondary-mobile-hide')+button('构建专题应用','go-apps','app','primary'),'SPATIAL DATA EXPLORER')}<div class="map-result-selector"><span>数据与成果</span><select id="map-source" aria-label="选择空间数据来源"><option value="fixture">仙桃农业 · 合成示例</option><optgroup label="数据集">${state.datasets.map(d=>`<option value="dataset:${esc(d.id)}" ${state.mapSource==='dataset:'+d.id?'selected':''}>${esc(d.name)} · ${d.feature_count} 要素</option>`).join('')}</optgroup><optgroup label="真实算法计算结果">${state.analyses.map(a=>`<option value="analysis:${esc(a.id)}" ${state.mapSource==='analysis:'+a.id?'selected':''}>${esc(algorithmName(a.algorithm_id))} · ${stamp(a.created_at)}</option>`).join('')}</optgroup><optgroup label="示例工作流成果">${completed.map(r=>`<option value="run:${esc(r.id)}" ${state.mapSource==='run:'+r.id?'selected':''}>${esc(r.name)} · ${stamp(r.created_at)}</option>`).join('')}</optgroup></select>${sourceBadge(currentSource().source_type)}</div>${mapPanel(true)}${result?provenanceCard(result):`<div class="notice" style="margin-top:16px">当前画布不调用地图底图服务。位置仅由数据自身坐标决定；上传数据应为 WGS84，经纬度顺序为经度、纬度。</div>`}`}
function flowNode(n,i){return `<button class="flow-node" data-action="node-detail" data-id="${esc(n.id)}"><span class="node-number">${String(i+1).padStart(2,'0')}</span><span class="node-info"><h3>${esc(n.name)}</h3><p>${esc(n.description)}</p></span><span class="tag neutral">查看配置</span></button>`}
function flowCanvas(p){const branches=p.nodes.filter(n=>n.id.startsWith('analyse-'));let branchInserted=false;return `<section class="panel flow-canvas"><div class="flow-title"><h2>${esc(p.name)}</h2><span class="tag">v${p.version} · ${p.nodes.length} 个节点</span></div>${p.nodes.map((n,i)=>{if(n.id.startsWith('analyse-')){if(branchInserted)return '';branchInserted=true;return `<div class="flow-line"></div><section class="branch-group"><div class="branch-heading"><b>业务分析分支</b><span>同源数据 · 本地按序执行</span></div><div class="branch-grid">${branches.map(b=>flowNode(b,p.nodes.indexOf(b))).join('')}</div><p>各分支依赖示例数据检索，统计结果汇入待核查图层。</p></section>`}return `${i?'<div class="flow-line"></div>':''}${flowNode(n,i)}`}).join('')}<div class="node-note">节点依赖与输入输出可查看 · 真实专业引擎待接入</div></section>`}
function workflow(){const p=state.plan;return `${heading('让复杂分析，成为清晰的流程','从业务语言出发，明确数据、专业能力与核查环节，再执行本地示例分析。',button('导出工作流','export-plan','download','secondary-mobile-hide',p?'':'disabled')+button('执行示例分析','run-plan','play','primary',!p||activeStatus(state.run?.status)?'disabled':''),'AI WORKFLOW ORCHESTRATION')}<div class="flow-layout"><aside class="panel flow-config"><div class="workflow-data-shortcut"><span>已有业务数据？</span><button class="text-button" data-action="go-lab">${icon('layers')}用我的数据分析 →</button></div><h2 class="subheading">需求与任务配置<span class="tag blue">规则辅助</span></h2><label class="field">业务需求<textarea id="requirement" placeholder="描述业务问题、空间区域及期望成果…">${esc(state.requirement)}</textarea></label><button class="text-button" data-action="full-demand" style="margin:-6px 0 16px">${icon('download')}导入仙桃完整业务需求</button><label class="field">分析区域<select id="region">${['湖北省 · 仙桃市','仙桃市 · 张沟镇','仙桃市 · 彭场镇'].map(r=>`<option ${r===state.region?'selected':''}>${r}</option>`).join('')}</select></label><label class="field">分析时相<select id="period">${['2025 / 2026 秋冬播对比','2026 春季 / 秋季对比','2026 年度业务台账'].map(r=>`<option ${r===state.period?'selected':''}>${r}</option>`).join('')}</select></label>${button(p?'更新需求计划':'生成分析计划','generate-plan','spark','primary block')}<p class="helper">识别多项业务目标，保留数据缺口。每个步骤的输入、输出与依赖均可查看。</p><div class="notice">当前执行的是本地示例数据空间统计。遥感影像获取、专业解译和真实业务核验需接入授权服务。</div>${state.plans.length?`<label class="field" style="margin-top:18px;margin-bottom:0">历史需求计划<select id="plan-select"><option value="">选择历史计划…</option>${state.plans.map(i=>`<option value="${esc(i.id)}" ${p?.id===i.id?'selected':''}>${esc(i.name)} · v${i.version}</option>`).join('')}</select></label>`:''}</aside><div class="flow-right">${p?planRequirements(p):`<section class="panel">${empty('从一项业务需求开始','输入需求或导入仙桃完整业务清单。<br>平台将梳理多主题目标、数据缺口与分析步骤。',button('导入完整业务需求','full-demand','flow'))}</section>`}<section class="panel" id="run-panel">${runPanel()}</section>${p?flowCanvas(p):''}</div></div>`}
function planRequirements(p){const rr=p.requirements||[];return `<section class="panel requirements"><div class="requirements-grid"><div><h3>已识别业务目标 · ${rr.length||1} 项</h3><div class="requirement-tags">${rr.length?rr.map(r=>`<span class="tag">${esc(r.title)}</span>`).join(''):`<span class="tag">${esc(p.name)}</span>`}</div><h3 style="margin-top:16px">预期成果</h3><div class="requirement-tags">${(p.deliverables||[]).map(d=>`<span class="tag blue">${esc(d)}</span>`).join('')}</div></div><div><h3>待补充与需确认的信息</h3><ul>${(p.gaps||[]).map(g=>`<li>${esc(g)}</li>`).join('')||'<li>执行前仍需确认授权数据与业务验收口径。</li>'}</ul></div></div></section>`}
function resultSummary(result){const summary=result.summary;if(typeof summary==='string')return `<p class="helper">${esc(summary)}</p>`;const v=summary||{},counts=v.counts_by_kind||{};return `<div class="summary-context"><span>${icon('pin')}${esc(v.region||'仙桃市')}</span><span>${icon('clock')}${esc(v.period||'任务时相')}</span></div><div class="summary-kinds">${Object.entries(counts).map(([k,n])=>`<span><i style="background:${colors[k]||'#8eb39b'}"></i>${esc(kindNames[k]||k)}<b>${n}</b></span>`).join('')}</div><p class="helper">${esc(v.message||'本地示例数据空间统计，非真实遥感识别或业务认定结果。')}</p>`}
function provenanceCard(result){const p=result.provenance||{};return `<section class="panel provenance-panel"><div class="panel-heading"><h2>${icon('shield')}成果来源与质量记录</h2><span class="tag amber">${esc(p.review_status||'待业务核查')}</span></div><div class="provenance-grid">${[['数据来源',p.source||'本机合成 GeoJSON'],['空间区域',p.region||(p.dataset_id?bboxText(state.datasets.find(d=>d.id===p.dataset_id)?.bbox):'未提供区域')],['分析时相',p.period||'输入未提供业务时相'],['生成时间',stamp(p.created_at)],['空间基准',p.crs||'EPSG:4326'],['任务标识',p.run_id||result.id||'—']].map(([n,v])=>`<div><small>${n}</small><b>${esc(v)}</b></div>`).join('')}</div><div class="provenance-note">${icon('info')}${p.source_type==='user'?'当前为用户输入数据的真实算法计算，输入来源与真实性由提供方负责。':'当前为本地合成示例计算，用于验证业务流程。'}真实监测与行政认定仍需授权数据和人工核查。</div><details class="technical-details"><summary>查看技术溯源记录</summary><pre class="code-block">${esc(JSON.stringify(p,null,2))}</pre></details></section>`}
function runPanel(){const r=state.run;return `<div class="panel-heading"><h2>${icon('flow')}任务运行记录${r?statusTag(r.status):''}</h2>${state.runs.length?`<select class="run-history-select" id="run-select" aria-label="历史任务"><option value="">选择运行记录…</option>${state.runs.map(i=>`<option value="${esc(i.id)}" ${r?.id===i.id?'selected':''}>${esc(i.name)} · ${statusName(i.status)}</option>`).join('')}</select>`:''}</div>${r?`<div class="run-body"><div class="run-description"><span>独立作业执行 · 页面切换后持续运行</span><span>${Math.round(r.progress||0)}%</span></div><div class="progress-bar"><span style="width:${Math.min(100,Math.max(0,r.progress||0))}%"></span></div>${(r.nodes||[]).map(n=>`<div class="node-run">${icon(n.status==='succeeded'?'check':n.status==='running'?'refresh':'clock')}<span>${esc(n.name)}</span><span>${esc(statusName(n.status))}</span></div>`).join('')}<div class="log-box" aria-label="运行日志">${(r.logs||[]).map(l=>`<div><time>${esc(stamp(l.time))}</time>${esc(l.message)}</div>`).join('')||'等待任务日志…'}</div>${r.result?`<div class="result-strip"><div><b>${r.result.feature_count}</b><small>空间要素</small></div><div><b>${Number(r.result.area_ha||0).toFixed(2)}</b><small>公顷 · 示例面要素</small></div><div><b>可追溯</b><small>来源 / 区域 / 时相</small></div></div>${resultSummary(r.result)}`:''}<div class="run-actions">${activeStatus(r.status)?button('取消任务','cancel-run','stop','danger small'):['failed','cancelled'].includes(r.status)?button('重试为新任务','retry-run','refresh','small'):''}${r.result?button('查看成果一张图','run-result','map','primary small')+button('导出成果','export-run','download','small'):''}${button('任务快照','run-snapshot','info','small')}</div><div class="trace">运行 ID ${esc(r.id)} · ${stamp(r.created_at)}</div></div>`:`<div class="empty-inline"><span>确认分析计划后执行。任务记录、日志与成果将保存在本地服务。</span></div>`}`}
function builder(){const a=state.appDraft;const mods=state.boot.modules;return `${heading('把专业能力，组装成业务应用','复用地图、分析和业务组件，为不同地区快速构建可持续迭代的专题。',button('保存草案','save-app','check')+button('发布与共享','publish-app','right','primary'),'LIGHTWEIGHT APPLICATION STUDIO')}<div class="builder-layout"><aside class="panel builder-config"><h2 class="subheading">应用配置<span class="tag">${state.apps.find(x=>x.id===state.appId)?.status==='published'?'已发布 · v'+a.version:state.appId?'已保存草案':'新建草案'}</span></h2><div class="app-select"><label class="sr-only" for="app-select">选择应用</label><select id="app-select"><option value="">＋ 新建专题应用</option>${state.apps.map(app=>`<option value="${esc(app.id)}" ${app.id===state.appId?'selected':''}>${esc(app.name)} · v${app.version}</option>`).join('')}</select></div>${state.apps.find(x=>x.id===state.appId)?.status==='published'?'<div class="notice" style="margin-bottom:16px">当前为已发布版本。编辑后保存会自动创建独立草案，保留原发布配置。</div>':''}<label class="field">应用名称<input id="app-name" maxlength="80" value="${esc(a.name)}" placeholder="为专题应用命名"></label><label class="field">应用说明<textarea class="app-description" id="app-description" maxlength="500">${esc(a.description)}</textarea></label><label class="field">界面主题<select id="app-theme"><option value="midnight" ${a.theme==='midnight'?'selected':''}>深海青 · 行业工作台</option><option value="light" ${a.theme==='light'?'selected':''}>浅叶绿 · 轻量专题</option></select></label><h3 class="subheading" style="font-size:11px;margin:22px 0 7px">业务组件<span class="muted" style="font-size:8px">选择即预览</span></h3><div class="check-grid">${mods.map(m=>`<label class="check-row"><input type="checkbox" data-module="${esc(m.id)}" ${a.modules.includes(m.id)?'checked':''}><span>${esc(m.name)}<small>${esc(m.category)}</small></span></label>`).join('')}</div><div class="notice">组件选择会改变专题导航、地图可见要素、指标与业务卡片。应用配置与原始数据分离。</div></aside><div id="app-preview-container">${appPreview()}</div></div>`}
function appPreview(){return empty('旧样例预览已移除','请从专题分析运行实际数据处理并查看成果。')}
function market(){const cats=['全部能力',...new Set(state.boot.modules.map(m=>m.category)),'工作空间应用'];let mods=state.marketCategory==='工作空间应用'?[]:state.boot.modules.filter(m=>(state.marketCategory==='全部能力'||m.category===state.marketCategory)&&(m.name+m.description).includes(state.marketSearch));let apps=state.apps.filter(a=>a.status==='published'&&(state.marketCategory==='全部能力'||state.marketCategory==='工作空间应用')&&(a.name+a.description).includes(state.marketSearch));return `${heading('让一次创新，成为共同的能力','发现可复用组件，将已验证的应用配置带到下一个业务现场。',button('发布我的应用','go-apps','plus','primary'),'OPEN CAPABILITY MARKETPLACE')}<div class="filter-row"><div class="pills">${cats.map(c=>`<button class="pill ${state.marketCategory===c?'active':''}" data-action="market-category" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="search-wrap">${icon('search')}<label class="sr-only" for="market-search">搜索能力</label><input id="market-search" class="search-input" placeholder="搜索组件、专题应用…" value="${esc(state.marketSearch)}"></div></div><div class="market-grid" id="market-results">${marketCards(mods,apps)}</div>`}
function marketCards(mods,apps){return mods.map(m=>`<article class="panel capability"><div class="scene-top"><span class="scene-symbol">${icon(({crop:'leaf',water:'water',eel:'cube',fishing:'shield',farmland:'layers'}[m.id])||'app')}</span><span class="tag">${esc(m.category)}</span></div><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p><div class="scene-bottom"><span>标准业务组件</span><span>配置复用</span></div>${button('加入应用工坊','reuse-module','plus','',`data-id="${esc(m.id)}"`)}</article>`).join('')+apps.map(a=>`<article class="panel capability"><div class="scene-top"><span class="scene-symbol">${icon('app')}</span><span class="tag blue">应用 v${a.version}</span></div><h3>${esc(a.name)}</h3><p>${esc(a.description||'可复用的专题应用配置')}</p><div class="scene-bottom"><span>${a.modules.length} 个组件 · 本机共享</span><span>版本化发布</span></div>${button('复用为新草案','clone-app','plus','',`data-id="${esc(a.id)}"`)}</article>`).join('')||`<section class="panel" style="grid-column:1/-1">${empty('没有匹配的能力','调整分类或搜索条件，也可在应用工坊创建专题应用。')}</section>`}
function filteredResources(){return state.boot.resources.filter(r=>(r.name+' '+r.type+' '+r.source).includes(state.dataSearch))}function legacyDataView(){return `${heading('统一数据入口，建立可信的空间底座','明确来源、时空粒度与授权状态，让业务数据可发现、可关联。','', 'SPATIAL DATA CATALOG')}<div class="filter-row"><div class="pills"><span class="tag">${state.boot.resources.length} 项建议资源</span><span class="tag neutral">来源权属独立 · 授权接入</span></div><div class="search-wrap">${icon('search')}<label class="sr-only" for="data-search">搜索数据资源</label><input id="data-search" class="search-input" placeholder="搜索名称、类型或来源…" value="${esc(state.dataSearch)}"></div></div><section class="panel table-wrap"><table class="resource-table"><thead><tr><th>数据资源</th><th>资源类型</th><th>时空粒度</th><th>拟接入来源</th><th>接入状态</th><th>操作</th></tr></thead><tbody id="resource-rows">${resourceRows()}</tbody></table></section><div class="catalog-note">${icon('info')}目录为建议接入清单，不代表已获得数据。需统一空间基准、业务编码、更新频次和授权范围。</div>`}
function resourceRows(){return filteredResources().map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.type)}</td><td>${esc(r.resolution)}</td><td>${esc(r.source)}</td><td><span class="tag ${r.status.includes('待')?'amber':'blue'}">${esc(r.status)}</span></td><td><button class="text-button" data-action="resource-detail" data-id="${esc(r.id)}">查看详情</button></td></tr>`).join('')||'<tr><td colspan="6" style="text-align:center;padding:45px">未找到匹配的数据资源</td></tr>'}
function connections(){return `${heading('让已有系统，协同起来','通过标准接口连接专业引擎与业务系统，复用既有建设成果。','','SYSTEM INTEGRATIONS')}<div class="architecture-banner"><div><strong>平台负责编排与交付，专业能力通过接口协作</strong>统一服务契约、保留数据权属、记录处理来源，让专业能力可调用、成果可追溯。</div><span class="tag">本机配置草案 · 未发起外部调用</span></div><div class="integration-grid">${state.boot.integrations.map(i=>`<section class="panel integration"><div class="scene-top"><span class="scene-symbol">${icon('link')}</span><span class="tag ${i.endpoint?'blue':'neutral'}">${i.endpoint?'已存草案':'待接入'}</span></div><h3>${esc(i.name)}</h3><p>${esc(i.description)}</p><div class="integration-meta">REST / OGC 服务 · 服务端凭据管理 · 接入后授权校验</div>${button('配置接口草案','integration-config','link','',`data-id="${esc(i.id)}"`)}${i.endpoint?`<div class="integration-state">已保存 ${esc(i.protocol)} · ${esc(i.endpoint)}</div>`:''}</section>`).join('')}</div>`}
let mapWorkspace=null,productionWorkspace=null,landcoverWorkspace=null,mapCopilot=null,sourcesWorkspace=null;
state.clientTab=safeGet('geoai-v11-panel-tab','applications');try{state.professionalMode=sessionStorage.getItem('geoai-professional-mode')==='true'}catch{state.professionalMode=false}
function getSources(){if(!sourcesWorkspace)sourcesWorkspace=new SourcesWorkspace({api,toast,showDialog,onImport:()=>actions['import-dialog'](),onDatasetMap:id=>showDatasetOnMap(id),onDatasets:()=>{state.dataAdvanced=true;state.professionalMode=true;go('data')},onProfessional:()=>{state.professionalMode=true;state.dataAdvanced=false;go('data')},onIntegrationChange:t=>mapWorkspace?.reloadMapSources(t),onPrepareAnalysis:async payload=>{if($('#dialog').open)closeDialog();const o=payload.observation;state.observationFootprint={item:{id:o.item_id||o.id,bbox:o.bbox},source_id:o.source_id,selection_token:Date.now()};await openClientTab('applications');await getMapCopilot().prepareObservation(payload);if(mapWorkspace?.map)await mapWorkspace.updateContext(mapContext())},onObservationMap:async o=>{if($('#dialog').open)closeDialog();state.observationFootprint={item:{id:o.item_id||o.id,bbox:o.bbox},source_id:o.source_id,selection_token:Date.now()};await openClientTab('map');if(mapWorkspace?.map)await mapWorkspace.updateContext(mapContext())},onBoundary:r=>{if($('#dialog').open)closeDialog();state.referenceBoundary={...r,selection_token:(state.referenceBoundary?.selection_token||0)+1};return openClientTab('map')}});return sourcesWorkspace}
