async function refresh(){const b=await api('/bootstrap');state.boot=b;state.plans=[];state.runs=[];state.apps=[];state.plan=null;state.run=null;state.appId=null;state.map={type:'FeatureCollection',features:[]};state.resultId='';await loadV3();$('#service-status').textContent='本地服务运行正常';render()}

async function init(){try{await refresh()}catch(e){$('#service-status').textContent='本地服务未连接';main.innerHTML=`<section class="error-state"><div class="eyebrow">WORKSPACE CONNECTION</div><h2>本地工作空间尚未连接</h2><p>${esc(e.message)}<br>请在项目目录运行 <code>python3 server.py</code>，然后重新连接。</p>${button('重新连接','reconnect','refresh','primary')}</section>`}}
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(state.polling||!state.runs.some(r=>activeStatus(r.status)))return;state.polling=true;try{const rr=await api('/runs');state.runs=rr;const previous=state.run?.status;if(state.run)state.run=rr.find(r=>r.id===state.run.id)||state.run;if(state.view==='workflow'&&$('#run-panel')){$('#run-panel').innerHTML=runPanel();const b=document.querySelector('[data-action="run-plan"]');if(b)b.disabled=!state.plan||activeStatus(state.run?.status)}if(['overview','map'].includes(state.view)&&mapWorkspace)mapWorkspace.updateContext(mapContext());if(previous&&activeStatus(previous)&&!activeStatus(state.run?.status)){toast(state.run.status==='succeeded'?'本地示例分析已完成，成果已持久化':`任务${statusName(state.run.status)}`)}}catch(e){$('#service-status').textContent='服务暂时不可用，任务状态待刷新'}finally{state.polling=false}},800)}
async function generatePlan(){const intent=/NDVI|植被指数/i.test(state.requirement)?'ndvi':/最近邻|最近距离|距离分析/.test(state.requirement)?'nearest':/空间统计|面积统计/.test(state.requirement)?'spatial_summary':null;if(intent){state.labAlgorithm=intent;showDialog('建议进入分析实验室',`<p>按本地规则识别到「${algorithmName(intent)}」需求。请选择输入数据，再执行对应真实算法。</p><div class="notice">此建议为关键词匹配；尚未调用大模型。NDVI需要red/nir字段，最近邻需要至少两个点。</div>`,button('前往选择数据','intent-to-lab','flow','primary'));return}if(!state.requirement.trim())throw Error('请先描述业务需求');const p=await api('/plans',{method:'POST',body:{requirement:state.requirement,region:state.region,period:state.period}});state.plan=p;state.plans=[p,...state.plans.filter(x=>x.id!==p.id)];safeSet('geoai-v2-requirement',state.requirement);safeSet('geoai-v2-plan-id',p.id);state.run=null;safeSet('geoai-v2-run-id',null);go('workflow');toast(`已生成分析计划，识别 ${p.requirements?.length||1} 项业务目标`)}
async function saveApp(){const a=state.appDraft;if(!a.name.trim())throw Error('请填写应用名称');if(!a.modules.length)throw Error('请至少选择一个业务组件');if(state.appId&&state.apps.find(x=>x.id===state.appId)?.status==='published'){const clone=await api('/apps/'+encodeURIComponent(state.appId)+'/clone',{method:'POST',body:{}});state.appId=clone.id;state.apps=[clone,...state.apps]}const result=await api(state.appId?'/apps/'+encodeURIComponent(state.appId):'/apps',{method:state.appId?'PATCH':'POST',body:{name:a.name.trim(),description:a.description,modules:a.modules,layer_ids:a.layer_ids||[],theme:a.theme}});state.appId=result.id;safeSet('geoai-v2-app-id',result.id);state.appDraft={...result,modules:[...result.modules]};state.apps=[result,...state.apps.filter(x=>x.id!==result.id)];return result}
