function featureDetail(id){const fs=state.view==='apps'?state.map.features:allFeatures();const f=fs.find((f,i)=>String(f.id??f.properties?.id??('index-'+i))===id);if(!f)return;const p=f.properties||{},meta=state.view==='apps'?{source_type:'synthetic'}:currentSource();showDialog(esc(p.name||p.id||'空间要素详情'),`<p>${sourceBadge(meta.source_type)} <span>数据属性按原始内容展示，未经独立核验。</span></p><div class="dialog-rows"><div class="dialog-row"><span>要素标识</span><span>${esc(f.id??'—')}</span></div><div class="dialog-row"><span>几何类型</span><span>${esc(f.geometry.type)}</span></div>${Object.entries(p).slice(0,20).map(([k,v])=>`<div class="dialog-row"><span>${esc(propertyLabels[k]||k)}</span><span>${esc(typeof v==='object'?JSON.stringify(v):v)}</span></div>`).join('')}</div><details class="technical-details"><summary>查看原始要素</summary><pre class="code-block">${esc(JSON.stringify(f,null,2))}</pre></details>`,button('关闭详情','close-dialog','check'))}
function guide(){showDialog('使用指南',`<p>查位置、看图层、做分析，结果留在同一张地图。</p><ol class="dialog-list"><li><b>找到位置：</b>搜索地名或坐标定位；需要分析时，点击“选择范围”明确选区。</li><li><b>选择任务：</b>从专题分析中选择业务，确认范围、日期和必要条件。也可直接描述需求。</li><li><b>查看结果：</b>完成后查看结论和地图，点击图斑或像元核查，下载同一份成果。</li><li><b>继续使用：</b>从任务与成果恢复分析，或在数据页上传自己的点位、轨迹和地块。</li></ol><div class="notice">年度分类产品与实际影像日期会单独标明；缺测区域不当作零值。尚未接入的业务会说明条件，不会用历史或示例数据代替。</div>`,button('进入专题分析','client-home','layers','primary'))}

function quick(id){state.requirement=id==='full'?FULL:id==='eel'?'构建仙桃市黄鳝养殖、加工与冷链物流全产业链专题一张图，并关联尾水治理情况。':'对比仙桃市秋冬播遥感影像，识别种植变化，关联确权地块并形成专题一张图。';safeSet('geoai-v2-requirement',state.requirement);if(state.view==='overview'){$('#assistant-prompt').value=state.requirement;$('#assistant-prompt').focus()}else{render();$('#requirement')?.focus()}toast(id==='full'?'已导入仙桃完整业务需求，点击生成分析计划':'已填入场景需求，可进一步修改')}
